\section{Introduction}

\subsection{The leak, and how to measure it}

A product $N=pq$ of two primes hides its factors, but not perfectly. The residue
of $N$ modulo a fixed $f$ constrains the residues of $p$ and $q$, and the
question of \emph{how much} it constrains them has a numerical answer.

The classical vehicle for such constraints is a character. Fix a modulus $f$ and
a surjective homomorphism
\[
\chi:(\mathbb Z/f\mathbb Z)^{\times}\longrightarrow G,\qquad |G|=n\ge 2,
\]
onto an abelian group $G$. Say that a prime $p\nmid f$ \emph{splits} when
$\chi(p)=1$; classically $\chi$ cuts out an abelian extension and $\chi(p)=1$ is
exactly the condition that $p$ splits completely there. For $n=2$ this is
quadratic residuacity, for $n=3$ cubic residuacity, and so on.

Two standard facts supply the probabilistic model: primes equidistribute among
the classes, so $\chi(p)$ is uniform on $G$; and $\chi$ is multiplicative, so
$\chi(N)=\chi(p)\chi(q)$. Hence:

\begin{quote}
\textbf{The fork model.} $\chi(p)$ and $\chi(q)$ are independent and uniform on
$G$; the observer sees $\chi(N)=\chi(p)\chi(q)$ and nothing else.
\end{quote}

We call the pair (hidden labels, observed product) a \emph{character-pinned
fork}.

\subsection{The wrong question and the right one}

The natural first question is Boolean: ``does at least one factor split?''\ One
can compute exactly how much $\chi(N)$ says about the answer, and at $n=2$ the
value is $I_\OR(2)=\tfrac32-\tfrac34\log_2 3=0.31128\ldots$ bits, a ceiling for
the OR question across every character and class-rate profile.

This is the wrong question. OR destroys information: it cannot distinguish
``exactly one splits'' from ``both split''. Since $pq=qp$, no observer can
distinguish the two factors, so the complete symmetric statistic is the
\emph{split-count}
\[
s=[\chi(p)=1]+[\chi(q)=1]\in\{0,1,2\},
\]
and every Boolean face is a deterministic function of $s$. Our object is
\[
\Is(n):=I\bigl(\text{class of }\chi(N)\,;\,s\bigr).
\]

\section{Preliminaries: finite information theory}

All entropies are in bits unless stated; $\log$ is the natural logarithm and
$\log_2 x=\log x/\log 2$.

\begin{definition}
A \emph{finite joint table} is $p:A\times B\to\mathbb R_{\ge0}$ on finite sets
with $\sum_{a,b}p(a,b)=1$. Its marginals are $p_A(a)=\sum_b p(a,b)$,
$p_B(b)=\sum_a p(a,b)$, and its mutual information is
\[
I(p)=\sum_{a,b}p(a,b)\log_2\frac{p(a,b)}{p_A(a)p_B(b)},
\]
zero cells contributing $0$. The entropy of a weight vector is
$H(q)=-\sum_i q_i\log_2 q_i$.
\end{definition}

\begin{lemma}[log-sum inequality]\label{lem:logsum}
For nonnegative $a_i$ and positive $b_i$,
\[
\sum_i a_i\log\frac{a_i}{b_i}\ \ge\ \Bigl(\sum_i a_i\Bigr)
\log\frac{\sum_i a_i}{\sum_i b_i},
\]
strictly as soon as some ratio $a_i/b_i$ differs from
$(\sum_j a_j)/(\sum_j b_j)$.
\end{lemma}

\begin{proof}[Proof sketch]
Pointwise, $x\log(x/y)-x\log c\ge x-cy$ for $x\ge0$, $y,c>0$, with equality iff
$x=cy$; sum with $c=(\sum a)/(\sum b)$.
\end{proof}

\begin{lemma}[data processing]\label{lem:dpi}
If $g:B\to C$ and $(g_*p)(a,c)=\sum_{b:g(b)=c}p(a,b)$, then $I(g_*p)\le I(p)$.
\end{lemma}

\begin{lemma}[input cap]\label{lem:cap}
$I(p)\le H(p_A)$; in particular $|A|=2$ implies $I(p)\le 1$ bit.
\end{lemma}

\begin{lemma}[channel decomposition]\label{lem:chan}
If $p(a,b)=w(a)k(a,b)$ with $w$ a prior and $k(a,\cdot)$ conditional laws, then
$I(p)=H\bigl(\sum_a w(a)k(a,\cdot)\bigr)-\sum_a w(a)H(k(a,\cdot))$.
\end{lemma}

\begin{lemma}[$\chi^2$ domination]\label{lem:chi2}
With
$\chi^2(p)=\sum_{a,b}\bigl(p(a,b)-p_A(a)p_B(b)\bigr)^2/\bigl(p_A(a)p_B(b)\bigr)$
one has $I(p)\log 2\le\chi^2(p)$.
\end{lemma}

\begin{lemma}[independence control]\label{lem:indep}
A product table $p(a,b)=w(a)v(b)$ has $I(p)=0$.
\end{lemma}

\section{The split-count channel}

Throughout $n\ge2$ and $x:=1/n$.

\begin{proposition}[conditional split-count laws]\label{prop:cond}
Write $A_1$ for the event $\chi(N)=1$ and $A_{\ne}$ for its complement. Then
$P(A_1)=1/n$ and
\[
P(s\mid A_1)=\Bigl(\tfrac{n-1}{n},0,\tfrac1n\Bigr),\qquad
P(s\mid A_{\ne})=\Bigl(\tfrac{n-2}{n},\tfrac2n,0\Bigr).
\]
\end{proposition}

\begin{proof}
Condition on $\chi(N)=c$; then $\chi(p)$ is uniform and $\chi(q)=c\chi(p)^{-1}$.
If $c=1$ the two factors split together or not at all, so $s\in\{0,2\}$ with
$P(s=2)=1/n$. If $c\ne1$ they cannot split together, while $\chi(p)=1$ and
$\chi(p)=c$ are disjoint events of probability $1/n$ each, so $P(s=1)=2/n$.
\end{proof}

Only the class of $\chi(N)$ (identity or not) enters: the channel input is
binary.

\begin{theorem}[binomial marginal]\label{thm:binom}
$s\sim\Bin(2,1/n)$: $P(s=0)=\bigl(\tfrac{n-1}{n}\bigr)^2$,
$P(s=1)=\tfrac{2(n-1)}{n^2}$, $P(s=2)=\tfrac1{n^2}$.
\end{theorem}

\begin{theorem}[the split-count law]\label{thm:law}
For every $n\ge2$,
\[
\Is(n)=H\bigl(\Bin(2,\tfrac1n)\bigr)
-\tfrac1n H\Bigl(\tfrac{n-1}{n},0,\tfrac1n\Bigr)
-\tfrac{n-1}{n}H\Bigl(\tfrac{n-2}{n},\tfrac2n,0\Bigr).
\]
In particular $\Is$ depends only on the order $n$: not on the modulus, not on
the group (cyclic or not), not on the particular character.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:chan} with prior $(1/n,(n-1)/n)$ and the rows of
Proposition~\ref{prop:cond}; the output marginal is $\Bin(2,1/n)$ by
Theorem~\ref{thm:binom}.
\end{proof}

\begin{theorem}[exact values]\label{thm:values}
\[
\Is(2)=1,\qquad \Is(3)=\log_2 3-\tfrac{10}{9}=0.4738513\ldots,
\]
\[
\Is(8)=\tfrac{117}{32}+\tfrac{21}{32}\log_2 3-\tfrac{105}{64}\log_2 7
=0.0905649\ldots
\]
\end{theorem}

\begin{proof}
Substitution. At $n=2$ the joint table is
$\bigl(\begin{smallmatrix}1/4&0&1/4\\0&1/2&0\end{smallmatrix}\bigr)$: the
observable determines the parity of $s$ exactly, and that parity is a fair coin.
\end{proof}

\begin{theorem}[sufficiency of the split-count]\label{thm:suff}
Let $e\in\{0,1\}^2$ be the ordered pair of split events. Then
$I(\text{class of }\chi(N);e)=\Is(n)$.
\end{theorem}

\begin{proof}[Proof sketch]
``$\le$'' is Lemma~\ref{lem:dpi}, since $s$ is the pushforward of $e$ under
$(e_1,e_2)\mapsto e_1+e_2$. For ``$\ge$'', the fork law is exchangeable, so the
two cells with $e_1+e_2=1$ are equal in every row; merging equal cells leaves
$u\log_2(u/v)$ unchanged.
\end{proof}

\begin{theorem}[which-factor wall]\label{thm:wall}
$I\bigl(\text{class of }\chi(N);[\chi(p)=1]\bigr)=0$ exactly.
\end{theorem}

\begin{proof}
$P(\chi(p)=1\mid\chi(N)=c)=1/n$ for every $c$, so the table is a product table;
apply Lemma~\ref{lem:indep}.
\end{proof}

\section{The one-bit cap and its equality case}

\begin{theorem}\label{thm:cap}
$\Is(n)\le1$ for all $n\ge2$, and $\Is(n)>0$: the fork is never vacuous.
\end{theorem}

\begin{proof}
The cap is Lemma~\ref{lem:cap} (binary input). Positivity: the cell $(A_1,s=1)$
has probability $0$ but positive independent-model value, so the strict form of
Lemma~\ref{lem:logsum} applies.
\end{proof}

\begin{theorem}[equality case for binary inputs]\label{thm:eqcase}
Let $p$ have two input symbols, positive marginals and arbitrary finite output
alphabet. If $I(p)=1$ bit then $p_A(0)=p_A(1)=1/2$.
\end{theorem}

\begin{proof}
$1=I(p)\le H(p_A)\le1$ forces $H(p_A)=1$, and a two-point distribution has
entropy one bit iff it is uniform.
\end{proof}

\begin{theorem}[the cap is attained exactly at the quadratic characters]
\label{thm:iff}
For $n\ge2$: $\Is(n)=1\iff n=2$.
\end{theorem}

\begin{proof}
$\Is(n)=1$ forces the class prior $(1/n,(n-1)/n)$ to be balanced by
Theorem~\ref{thm:eqcase}, i.e. $n=2$; conversely $\Is(2)=1$.
\end{proof}

The argument is purely prior-theoretic and applies verbatim to \emph{any}
zero/one splitting profile with unbalanced class prior. It also explains an
exhaustive numerical finding. Let a \emph{splitting profile} on a modulus $f$ be
an arbitrary subset $S$ of the unit group $U$ modulo $f$, a prime being declared
split when its residue lies in $S$; take as observable the \emph{full} residue
class of $N=pq$ --- one of $|U|$ symbols, not a binary flag --- and compute the
exact information it carries about the split-count. Enumerating all $2^{|U|}$
profiles on nine moduli, including the non-cyclic unit groups $C_2\times C_2$,
$C_2\times C_4$, $C_2\times C_2\times C_2$ and $C_2\times C_6$, the maximum is
exactly $1.000000$ bits in every case, and the maximisers are exactly the
index-two subgroups --- the kernels of the quadratic characters --- together
with their complementary cosets (complementing the splitting predicate sends $s$
to $2-s$, which cannot change the information).

\section{The Boolean faces}

Every Boolean question factors through $s$:
$\OR=\mathbf 1[s\ge1]$, $\AND=\mathbf 1[s=2]$, $\XOR=\mathbf 1[s=1]$.

\begin{theorem}\label{thm:faces}
For every $g:\{0,1,2\}\to\{0,1\}$ the information carried by $g(s)$ is at most
$\Is(n)$.
\end{theorem}

With $H_b$ the binary entropy in bits,
\[
I_\AND(n)=H_b\Bigl(\tfrac1{n^2}\Bigr)-\tfrac1nH_b\Bigl(\tfrac1n\Bigr),\qquad
I_\OR(n)=H_b\Bigl(\tfrac2n-\tfrac1{n^2}\Bigr)-\tfrac1nH_b\Bigl(\tfrac1n\Bigr)
-\Bigl(1-\tfrac1n\Bigr)H_b\Bigl(\tfrac2n\Bigr),
\]
obtained from Lemma~\ref{lem:chan} applied to
\[
k_\AND=\begin{pmatrix}1-\tfrac1n&\tfrac1n\\1&0\end{pmatrix},\qquad
k_\OR=\begin{pmatrix}1-\tfrac1n&\tfrac1n\\1-\tfrac2n&\tfrac2n\end{pmatrix},
\]
both with prior $(1/n,1-1/n)$.

\subsection{The mirror principle}

Both faces share a prior and a first row and differ only in the second row,
$\Bern(0)$ for AND and $\Bern(2x)$ for OR with $x=1/n$: mirror images about the
\emph{useless} value $q=x$, where the rows would coincide. For $x\in(0,1)$ and
$q\in[0,1]$ let
\[
\mathcal I(x,q)=H\bigl(x^2+(1-x)q\bigr)-xH(x)-(1-x)H(q),
\]
with $H(y)=-y\log y-(1-y)\log(1-y)$ in nats.

\begin{theorem}[mirror principle]\label{thm:mirror}
Let $0<t\le x<1/2$. Then $\mathcal I(x,x+t)<\mathcal I(x,x-t)$: with an
unbalanced prior, a second row that undershoots the useless value by $t$ is
strictly more informative than one that overshoots it by $t$.
\end{theorem}

\begin{proof}
The output-marginal probabilities are $x^2+(1-x)(x\pm t)=x\pm(1-x)t$, so with
$\varphi(u):=H(x+u)-H(x-u)$ the difference
$\mathcal I(x,x+t)-\mathcal I(x,x-t)$ equals
$\varphi\bigl((1-x)t\bigr)-(1-x)\varphi(t)$. Thus the claim is the strict
sub-homogeneity $\varphi(\lambda t)<\lambda\varphi(t)$ with $\lambda=1-x$. For
$0<u<x$,
\[
\varphi'(u)=\log\frac{(1-x)^2-u^2}{x^2-u^2},
\]
and for $0\le d<e<x$,
\[
\bigl((1-x)^2-e^2\bigr)\bigl(x^2-d^2\bigr)-\bigl((1-x)^2-d^2\bigr)\bigl(x^2-e^2\bigr)
=(1-2x)(e^2-d^2)>0
\]
precisely because $x<1/2$; hence $\varphi'$ is strictly increasing on $[0,x)$.
Since $\varphi(0)=0$, the mean value theorem gives $d\in(0,\lambda t)$ and
$e\in(\lambda t,t)$ with
\[
\frac{\varphi(\lambda t)}{\lambda t}=\varphi'(d)<\varphi'(e)
=\frac{\varphi(t)-\varphi(\lambda t)}{t-\lambda t},
\]
and clearing denominators finishes the proof.
\end{proof}

\begin{theorem}[AND strictly beats OR for $n>2$]\label{thm:andor}
For every real $n>2$, $I_\OR(n)<I_\AND(n)$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:mirror} with $x=1/n<1/2$ and $t=x$: OR is
$\mathcal I(x,x+t)$ and AND is $\mathcal I(x,x-t)$; divide by $\log 2$.
\end{proof}

\begin{theorem}[coincidence at the quadratic characters]\label{thm:n2}
$I_\AND(2)=I_\OR(2)=\tfrac32-\tfrac34\log_23=0.3112781\ldots$ and
$I_\XOR(2)=\Is(2)=1$.
\end{theorem}

At $x=1/2$ the derivative $\varphi'$ is constant in $u$, which is exactly why
the mirror principle degenerates there.

\begin{corollary}
$I_\OR(n)\le I_\AND(n)$ for all $n\ge2$, with equality iff $n=2$. Moreover
$I_\OR(2)=0.31128\ldots<1=\Is(2)$: the celebrated OR ceiling is a projection
artifact, exceeded by the complete channel by a factor of $3.21$.
\end{corollary}

\subsection{The honest hierarchy correction}

At $n=3$,
\[
I_\OR(3)=\log_23-\tfrac59\log_25-\tfrac29=0.072780\ldots,\quad
I_\AND(3)=\tfrac53\log_23-\tfrac{22}9=0.197160\ldots,
\]
\[
I_\XOR(3)=\tfrac43\log_23-\tfrac59\log_25-\tfrac49=0.378879\ldots,\quad
\Is(3)=0.473851\ldots,
\]
so $I_\OR<I_\AND<I_\XOR<\Is$. The chain does not persist.

\begin{proposition}[crossover at $n=8$]\label{prop:eight}
\[
I_\OR(8)=\tfrac{31}8+\tfrac{27}{64}\log_23-\tfrac{15}{64}\log_25
-\tfrac{91}{64}\log_27=0.0077455\ldots,
\]
\[
I_\XOR(8)=\tfrac{13}4+\tfrac{21}{32}\log_23-\tfrac{25}{16}\log_25
-\tfrac7{32}\log_27=0.0480098\ldots,
\]
\[
I_\AND(8)=\tfrac{45}8-\tfrac{63}{32}\log_23-\tfrac78\log_27=0.0481700\ldots,
\qquad \Is(8)=0.0905650\ldots,
\]
so $I_\OR(8)<I_\XOR(8)<I_\AND(8)<\Is(8)$: AND overtakes XOR. Numerically
$I_\XOR\ge I_\AND$ holds iff $n\le7$.
\end{proposition}

\begin{proof}
Each inequality reduces to a comparison of integer powers, e.g.
$3^{84}\cdot7^{21}<2^{76}\cdot5^{50}$ for $I_\XOR(8)<I_\AND(8)$,
$2^{40}\cdot5^{85}<3^{15}\cdot7^{77}$ for $I_\OR(8)<I_\XOR(8)$, and
$2^{126}\cdot7^{49}<3^{168}$ for $I_\AND(8)<\Is(8)$.
\end{proof}

The surviving universals are: $\Is\ge$ every projection at every order;
$I_\AND\ge I_\OR$ at every order; and $I_\XOR\ge I_\AND$ exactly for $n\le7$.

\section{Asymptotics}

\begin{theorem}[exact four-cell expansion]\label{thm:expansion}
For $n\ge2$, with $x=1/n$,
\[
\Is(n)\log2=3x(1-x)\bigl(-\log(1-x)\bigr)+x^2\log n
+(1-x)(1-2x)\log\frac{1-2x}{(1-x)^2}.
\]
\end{theorem}

\begin{theorem}[two-sided bounds and sharp rate]\label{thm:bounds}
For all $n\ge2$,
\[
\frac{1+\log n}{n^2\log2}\ \le\ \Is(n)\ \le\ \frac{3+\log n}{n^2\log2},
\qquad\text{hence}\qquad
\lim_{n\to\infty}\frac{n^2\Is(n)}{\log_2 n}=1 .
\]
\end{theorem}

\begin{theorem}[exact additive constant]\label{thm:const}
For every real $n\ge3$,
$\bigl|n^2\Is(n)\log2-\log n-2\bigr|\le 2/n$; hence
$n^2\Is(n)\log2-\log n\to2$, equivalently
$n^2\Is(n)-\log_2n\to 2/\log2=2.8854\ldots$
\end{theorem}

The constant $2$ decomposes as $+3$ from the three cells in which exactly one
factor splits, minus $1$ from the majority-class cell.

\begin{theorem}[second-order term]\label{thm:second}
For every real $n\ge3$,
$\bigl|n^2\Is(n)\log2-\log n-2+\tfrac1{2n}\bigr|\le 12/n^2$; hence
$n\bigl(n^2\Is(n)\log2-\log n-2\bigr)\to-\tfrac12$.
\end{theorem}

Consequently
\[
\Is(n)=\frac{\log n+2-\frac1{2n}+O(n^{-2})}{n^2\log2}.
\]

\begin{proposition}[two refutations]\label{prop:refute}
There is no $c>0$ with $\Is(n)\ge c/n$ for all $n\ge2$ (indeed $n\Is(n)\to0$),
and $n\Is(n)/\log_2n\to0$ rather than $1$: the correct normalisation is $n^2$.
\end{proposition}

\section{Forks of higher arity}

Let $N=p_1\cdots p_r$ with $r\ge2$ independent uniform labels and let $k$ count
the split factors.

\begin{definition}\label{def:arity}
Put $a_m=\bigl((n-1)^m+(n-1)(-1)^m\bigr)/n$, the number of $m$-tuples of
non-identity classes whose product is the identity. The arity-$r$ table is
\[
p(A_1,k)=\binom rk\frac{a_{r-k}}{n^r},\qquad
p(A_{\ne},k)=\binom rk\frac{(n-1)^{r-k}-a_{r-k}}{n^r},
\]
with mutual information $I^{(r)}(n)$.
\end{definition}

\begin{theorem}\label{thm:aritybasics}
The split-count marginal is $\Bin(r,1/n)$ at every arity; $I^{(2)}(n)=\Is(n)$;
$I^{(r)}(n)\le1$ for all $r\ge1$; $I^{(r)}(2)=1$ for all $r\ge1$; and
$I^{(r)}(n)<1$ for $r\ge2$, $n\ge3$.
\end{theorem}

\begin{theorem}[exact $\chi^2$ divergence]\label{thm:chi2fork}
For $r\ge1$, $n\ge2$: $\chi^2\bigl(p^{(r)}\bigr)=(n-1)^{1-r}$.
\end{theorem}

\begin{proof}[Proof sketch]
The deviation from independence in column $k$ is proportional to
$\binom rk(n-1)^{-(r-k)}$; summing with
$\sum_k\binom rk y^{r-k}=(1+y)^r$ at $y=1/(n-1)$ collapses to $(n-1)^{1-r}$.
\end{proof}

\begin{theorem}[no-amplification law]\label{thm:noamp}
$I^{(r)}(n)\le (n-1)^{1-r}/\log2$; for fixed $n\ge3$, $I^{(r)}(n)\to0$
geometrically as $r\to\infty$.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:chi2} with Theorem~\ref{thm:chi2fork}.
\end{proof}

\begin{theorem}[the arity constant]\label{thm:arityconst}
For fixed $r\ge2$ and real $n\ge3$,
\[
\bigl|n^rI^{(r)}(n)\log2-\log n-r\bigr|\le\frac{2r}{n-1}+\frac{6\cdot2^r}{n},
\]
hence $n^rI^{(r)}(n)\log2-\log n\to r$.
\end{theorem}

\begin{proof}[Proof sketch]
Group by the number $m=r-k$ of non-splitting factors; the column contribution is
$\binom rm T(n,m)/n^{r+1}$ with
\[
T(n,m)=\bigl((n-1)^m+(n-1)(-1)^m\bigr)\log\frac{(n-1)^m+(n-1)(-1)^m}{(n-1)^m}
+(n-1)\bigl((n-1)^m-(-1)^m\bigr)\log\frac{(n-1)^m-(-1)^m}{(n-1)^m}.
\]
Then $T(n,0)=n\log n$, $T(n,1)=(n-1)n\log\frac n{n-1}$, and $|T(n,m)|\le6$ for
$m\ge2$; since $(n-1)\log\frac n{n-1}=1+O(1/n)$, the two leading columns supply
$\log n+r$ and the tail is $O(2^r/n)$.
\end{proof}

For $r=2$ this recovers Theorem~\ref{thm:const}: the constant is the arity.

\section{The arithmetic anchor}

\begin{theorem}[zero-sum counts]\label{thm:zerosum}
Let $n\ge2$, $m\ge0$. The number of $m$-tuples of nonzero elements of
$\mathbb Z/n\mathbb Z$ summing to $0$ is
$A_m=\bigl((n-1)^m+(n-1)(-1)^m\bigr)/n$, and for any fixed $c\ne0$ the number
summing to $c$ is $B_m=\bigl((n-1)^m-(-1)^m\bigr)/n$ --- the same for every
nonzero target, whether or not $n$ is prime.
\end{theorem}

\begin{proof}
Peel off the first coordinate: $A_{m+1}=(n-1)B_m$ and
$B_{m+1}=A_m+(n-2)B_m$, with $A_0=1$, $B_0=0$. The characteristic roots are
$n-1$ and $-1$, giving the stated closed forms.
\end{proof}

For composite $n$ no unit acts transitively on the nonzero classes, so the
uniformity of $B_m$ over nonzero targets is a consequence of the recursion, not
of a symmetry. It is what makes the arity-$r$ table order-universal for
non-cyclic groups as well.

\section{Why the leak is factoring-inert}

\begin{enumerate}
\item[(a)] \textbf{Symmetry.} By Theorem~\ref{thm:wall} the split event of a
designated factor is exactly independent of the observable: the channel reports
how many factors split, never which.
\item[(b)] \textbf{A residue dial.} Everything delivered is a function of
$N\bmod f$, computable in polynomial time from $N$ alone.
\item[(c)] \textbf{The Chinese Remainder seal.} For composite moduli the
character factors through the CRT decomposition; combining $t$ moduli yields at
most $\sum_i\Is(n_i)$ bits, each about a separately computable residue.
\item[(d)] \textbf{Classical reciprocity, quantified.} At $n=2$ the full bit is
the Jacobi symbol of $N$: the parity of the number of non-residue factors, known
to be efficiently computable and factoring-useless.
\item[(e)] \textbf{Arity kills it.} By Theorem~\ref{thm:noamp} the leak decays
geometrically in the number of factors for $n\ge3$.
\end{enumerate}

Numerical experiments confirm the model. Over tens of thousands of semiprimes
below $2^{22}$ across eight moduli, the measured channel tracks the closed form:
at order $3$, moduli $7$, $9$, $21$ give $0.4731$, $0.4718$, $0.4755$ against
$0.47385$; at order $4$, modulus $16$ gives $0.2894$ against $0.29474$; at order
$5$, modulus $11$ gives $0.2060$ against $0.20271$; at order $6$, modulus $7$
gives $0.1482$ against $0.14868$. Empirical split-count distributions match
$\Bin(2,1/n)$ throughout, and the which-factor channel measures $0.0000$--$0.0003$
bits. Controls behave: characters on moduli coprime to the observable register
$0.0001$--$0.0003$ bits, and replacing the modulus by its square leaves the
channel invariant.

\section{Algorithms}

\textbf{Algorithm A (exact channel evaluation).} Build the $2\times3$ table
$\pi_ak_{a,s}$ with $\pi=(1/n,(n-1)/n)$ and the rows of
Proposition~\ref{prop:cond}, then sum $p\log_2\frac{p}{p_Ap_B}$ over the four
nonzero cells; cost $O(1)$. With a pushforward map it evaluates any Boolean
face; with Definition~\ref{def:arity} it evaluates $I^{(r)}(n)$ in $O(r)$
operations.

\textbf{Algorithm B (empirical estimation).} Sieve primes to a bound $B$, form
semiprimes coprime to $f$, tabulate $\bigl([\chi(N)=1],s\bigr)$, and return the
plug-in mutual information; cost $O(B\log\log B)+O(M)$. The plug-in estimator is
biased upward by about $(\#\text{cells})/(2M\log2)$.

\textbf{Algorithm C (profile enumeration).} For a fixed modulus $f$ with unit
group $U$, enumerate all $2^{|U|}$ zero/one profiles and compute the exact
channel for each; cost $O(2^{|U|}|U|^2)$, feasible for $|U|\le20$.

\section{Discussion and future directions}

Three lessons. \emph{Choose the sufficient statistic before quoting a ceiling}:
the $0.3113$-bit OR ceiling is sharp for the OR question but understates the
fork by a factor of $3.21$. \emph{Unbalanced priors break Boolean symmetry}: the
mirror principle is a general fact about binary channels, of which ``AND beats
OR'' is a corollary. \emph{Beware plausible hierarchies}: the chain
$\Is\ge I_\XOR\ge I_\AND\ge I_\OR$ crosses over at $n=8$.

Open directions: (1) the $n$-ary observable (the full class of $\chi(N)$),
capped by $\log_2n$ rather than one bit; (2) correlated label models for
restricted prime families; (3) non-abelian pinning, where ``split'' is a
conjugacy-class condition; (4) the full curvature of $q\mapsto\mathcal I(x,q)$,
giving sharp bounds for arbitrary noisy projections; (5) exact conditions under
which multi-modulus fork channels are jointly independent; (6) estimator theory
matched to a channel of size $O(\log n/n^2)$.

